    "rankMathHead": "<meta name=\"description\" content=\"Explore how self-esteem and self-criticism develop, why harsh self-judgment can persist, and how counselling can support a more balanced sense of self.\"/>\n<meta name=\"robots\" content=\"index, follow, max-snippet:-1, max-video-preview:-1, max-image-preview:large\"/>\n<link rel=\"canonical\" href=\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism\" />\n<meta property=\"og:locale\" content=\"en_US\" />\n<meta property=\"og:type\" content=\"article\" />\n<meta property=\"og:title\" content=\"Why Is My Self-Esteem So Low? | ChangeMoment\" />\n<meta property=\"og:description\" content=\"Explore how self-esteem and self-criticism develop, why harsh self-judgment can persist, and how counselling can support a more balanced sense of self.\" />\n<meta property=\"og:url\" content=\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism\" />\n<meta property=\"og:site_name\" content=\"ChangeMoment Mental Health Centre\" />\n<meta property=\"article:tag\" content=\"Counselling\" />\n<meta property=\"article:tag\" content=\"Mental Health\" />\n<meta property=\"article:tag\" content=\"Self-Criticism\" />\n<meta property=\"article:tag\" content=\"Self-Esteem\" />\n<meta property=\"article:tag\" content=\"Self-Worth\" />\n<meta property=\"article:section\" content=\"Uncategorized\" />\n<meta property=\"og:updated_time\" content=\"2026-08-28T19:24:52+00:00\" />\n<meta property=\"og:image\" content=\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\" />\n<meta property=\"og:image:secure_url\" content=\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\" />\n<meta property=\"og:image:width\" content=\"1920\" />\n<meta property=\"og:image:height\" content=\"1080\" />\n<meta property=\"og:image:alt\" content=\"Why Is My Self-Esteem So Low? Understanding Self-Worth and Self-Criticism\" />\n<meta property=\"og:image:type\" content=\"image/jpeg\" />\n<meta property=\"article:published_time\" content=\"2026-08-28T16:01:57+00:00\" />\n<meta property=\"article:modified_time\" content=\"2026-08-28T19:24:52+00:00\" />\n<meta name=\"twitter:card\" content=\"summary_large_image\" />\n<meta name=\"twitter:title\" content=\"Why Is My Self-Esteem So Low? | ChangeMoment\" />\n<meta name=\"twitter:description\" content=\"Explore how self-esteem and self-criticism develop, why harsh self-judgment can persist, and how counselling can support a more balanced sense of self.\" />\n<meta name=\"twitter:image\" content=\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\" />\n<meta name=\"twitter:label1\" content=\"Written by\" />\n<meta name=\"twitter:data1\" content=\"changemoment_admin\" />\n<meta name=\"twitter:label2\" content=\"Time to read\" />\n<meta name=\"twitter:data2\" content=\"6 minutes\" />\n<script type=\"application/ld+json\" class=\"rank-math-schema\">{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":[\"Person\",\"Organization\"],\"@id\":\"https://changemoment.ca/cms/#person\",\"name\":\"ChangeMoment Mental Health Centre\"},{\"@type\":\"WebSite\",\"@id\":\"https://changemoment.ca/cms/#website\",\"url\":\"https://changemoment.ca/cms\",\"name\":\"ChangeMoment Mental Health Centre\",\"publisher\":{\"@id\":\"https://changemoment.ca/cms/#person\"},\"inLanguage\":\"en-US\"},{\"@type\":\"ImageObject\",\"@id\":\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\",\"url\":\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\",\"width\":\"1920\",\"height\":\"1080\",\"caption\":\"Why Is My Self-Esteem So Low? Understanding Self-Worth and Self-Criticism\",\"inLanguage\":\"en-US\"},{\"@type\":\"WebPage\",\"@id\":\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism#webpage\",\"url\":\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism\",\"name\":\"Why Is My Self-Esteem So Low? | ChangeMoment\",\"datePublished\":\"2026-08-28T16:01:57+00:00\",\"dateModified\":\"2026-08-28T19:24:52+00:00\",\"isPartOf\":{\"@id\":\"https://changemoment.ca/cms/#website\"},\"primaryImageOfPage\":{\"@id\":\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\"},\"inLanguage\":\"en-US\"},{\"@type\":\"Person\",\"@id\":\"https://changemoment.ca/cms/author/changemoment_admin/\",\"name\":\"changemoment_admin\",\"url\":\"https://changemoment.ca/cms/author/changemoment_admin/\",\"image\":{\"@type\":\"ImageObject\",\"@id\":\"https://secure.gravatar.com/avatar/d03548a8019cafd0da5423d2d641e954e532bf01a157fcad06b51c973cb291dc?s=96&amp;d=mm&amp;r=g\",\"url\":\"https://secure.gravatar.com/avatar/d03548a8019cafd0da5423d2d641e954e532bf01a157fcad06b51c973cb291dc?s=96&amp;d=mm&amp;r=g\",\"caption\":\"changemoment_admin\",\"inLanguage\":\"en-US\"}},{\"@type\":\"BlogPosting\",\"headline\":\"Why Is My Self-Esteem So Low? | ChangeMoment\",\"keywords\":\"low self-esteem\",\"datePublished\":\"2026-08-28T16:01:57+00:00\",\"dateModified\":\"2026-08-28T19:24:52+00:00\",\"articleSection\":\"Uncategorized\",\"author\":{\"@id\":\"https://changemoment.ca/cms/author/changemoment_admin/\",\"name\":\"changemoment_admin\"},\"publisher\":{\"@id\":\"https://changemoment.ca/cms/#person\"},\"description\":\"Explore how self-esteem and self-criticism develop, why harsh self-judgment can persist, and how counselling can support a more balanced sense of self.\",\"name\":\"Why Is My Self-Esteem So Low? | ChangeMoment\",\"@id\":\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism#richSnippet\",\"isPartOf\":{\"@id\":\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism#webpage\"},\"image\":{\"@id\":\"https://changemoment.ca/cms/wp-content/uploads/2026/08/blog-3-Why-Is-My-Self-Esteem-So-Low-1-1.jpg\"},\"inLanguage\":\"en-US\",\"mainEntityOfPage\":{\"@id\":\"https://changemoment.ca/blogs/why-is-my-self-esteem-so-low-understanding-self-worth-and-self-criticism#webpage\"}}]}</script>\n"
